#!/usr/bin/env bats

load test_helper

@test "summarizes a mixed result file" {
  run "${REPO_ROOT}/bin/report.sh" "${REPO_ROOT}/data/sample.csv"
  [ "$status" -eq 0 ]
  [ "$output" = "total=3 passed=2 failed=1" ]
}

@test "reports usage when no file is given" {
  run "${REPO_ROOT}/bin/report.sh"
  [ "$status" -eq 64 ]
}

@test "reports a missing file on stderr" {
  run "${REPO_ROOT}/bin/report.sh" "${REPO_ROOT}/data/absent.csv"
  [ "$status" -eq 66 ]
}
# Shared setup for the bats files in this directory.

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
export REPO_ROOT
.PHONY: test

test:
	@bats test/
# buildreport

`bin/report.sh FILE` summarizes a CSV of build results as one line of counters.

Tests use bats-core. Files live in `test/` as `*.bats` and load `test/test_helper.bash`.
Run them with `make test`, which calls `bats test/`.
/usr/bin/bats
/usr/bin/jq

